<script setup lang="ts">
import SoftSelect from '../components/SoftSelect.vue'
import { ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, post, query, datetime, businessDate,contextVersion } from '../lib/api'
import { isParent } from '../lib/state'
import { useResource, loadStudents, openDialog, studentOptions, subjectOptions, act, label, notify } from '../lib/ui'
import type { Mistake, Attachment } from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
import StatusBadge from '../components/StatusBadge.vue'
import AttachmentList from '../components/AttachmentList.vue'
const route=useRoute();const studentId=ref<string | number>(String(route.query.studentId||''));const subject=ref('');const status=ref('');const detail=ref<Mistake|null>(null)
const book=ref<Attachment|null>(null),printing=ref(false)
watch([studentId,subject,contextVersion],()=>{book.value=null})
const students=useResource(loadStudents)
const {data,loading,error,refresh}=useResource(()=>api<Mistake[]>(`/mistakes${query({studentId:studentId.value,subject:subject.value,status:status.value})}`),[studentId,subject,status])
async function printBook(){if(!studentId.value){notify('请先选择一个孩子，再生成打印本','error');return}printing.value=true;await act(async()=>{book.value=await post<Attachment>('/mistake-books',{studentId:Number(studentId.value),subject:subject.value})},'PDF已生成，打开文件即可保存或打印');printing.value=false}
async function create() {
  if(await openDialog({title:'记录一道成长错题',description:'找到知识盲点，陪孩子把“不会”变成“掌握”。',fields:[{key:'studentId',label:'学生',type:'select',required:true,options:studentOptions(students.data.value||[])},{key:'subject',label:'科目',type:'select',required:true,options:subjectOptions},{key:'title',label:'题目 / 错题标题（与照片至少填写一项）',type:'textarea'},{key:'knowledgePoint',label:'知识点（可后补）'},{key:'errorReason',label:'错误原因（可后补）',type:'textarea'},{key:'attachmentIds',label:'题目附件',type:'file'}],initial:{studentId:studentId.value?Number(studentId.value):'',subject:'数学',...(route.query.homeworkId?{homeworkId:Number(route.query.homeworkId)}:{})},submit:v=>post('/mistakes',v),success:'错题已加入成长档案'}))refresh()
}
async function correct(item:Mistake) {
  if(await openDialog({title:`提交订正 · ${item.studentName}`,description:item.title,fields:[{key:'text',label:'订正过程与思考',type:'textarea',required:true},{key:'attachmentIds',label:'订正附件',type:'file'}],initial:{text:item.correctionText||''},submit:v=>post(`/mistakes/${item.id}/correct`,v),success:'订正已提交，等待老师审核'})){detail.value=null;refresh()}
}
async function review(item:Mistake) {
  if(await openDialog({title:`审核错题 · ${item.studentName}`,description:'通过审核后，系统按积分规则奖励，并生成 1、3、7 天复习任务。',fields:[{key:'approved',label:'审核结论',type:'select',required:true,options:[{value:'yes',label:'已掌握，通过审核'},{value:'no',label:'仍需订正，退回修改'}]},{key:'comment',label:'审核评语',type:'textarea',required:true}],initial:{approved:'yes',comment:item.teacherComment||''},submit:v=>post(`/mistakes/${item.id}/review`,{approved:v.approved==='yes',comment:v.comment}),success:'审核结果已保存'})){detail.value=null;refresh()}
}
async function complete(id:number) {if(await act(()=>post(`/mistakes/reviews/${id}/complete`),'复习任务已完成')){detail.value=null;refresh()}}
</script>
<template><PageHeader title="成长错题本" subtitle="错题不是终点，是下一次进步的起点。"><button class="btn secondary" :disabled="printing||!studentId" @click="printBook">生成打印本</button><RouterLink v-if="!isParent" class="btn secondary" :to="`/capture?studentId=${studentId}&kind=MISTAKE`">拍照录题</RouterLink><button class="btn primary" @click="create"><AppIcon name="Plus" :size="17" />记录错题</button></PageHeader><section v-if="book" class="panel" style="padding:20px;margin-bottom:20px"><strong>打印本已生成</strong><AttachmentList :files="[book]" /><p class="form-hint">打开PDF后使用系统打印或保存到文件。</p></section><section class="panel"><div class="filter-bar"><SoftSelect v-model="studentId" aria-label="错题学生" :options="[{value:'',label:'全部学生'}, ...(students.data.value || []).map(s => ({value:s.id,label:s.name}))]" /><SoftSelect v-model="subject" aria-label="错题科目" :options="[{value:'',label:'全部科目'}, ...subjectOptions]" /><SoftSelect v-model="status" aria-label="错题状态" :options="[{value:'',label:'全部状态'},{value:'UNCORRECTED',label:'待订正'},{value:'PENDING_REVIEW',label:'待审核'},{value:'MASTERED',label:'已掌握'}]" /><span class="filter-count">共 {{ data?.length||0 }} 道成长足迹</span><button class="icon-btn" aria-label="刷新错题" @click="refresh"><AppIcon name="RefreshCw" :size="17" /></button></div><LoadState :loading="loading" :error="error" :empty="!data?.length" title="知识的种子正在慢慢生长" description="记录错题、提交订正、定期复习，让掌握更扎实。" @retry="refresh"><div class="mistake-grid"><article v-for="item in data" :key="item.id" class="mistake-card"><div class="card-top"><span class="subject-tag">{{ item.subject }}</span><StatusBadge :value="item.status" /></div><h3><button @click="detail=item">{{ item.title }}</button></h3><p class="muted">{{ item.knowledgePoint }}</p><div class="mistake-reason"><AppIcon name="Lightbulb" :size="16" />{{ item.errorReason||'等待记录错误原因' }}</div><div class="card-bottom"><span>{{ item.studentName }}<small v-if="item.campusName">{{ item.campusName }}</small><small>{{ datetime(item.createdAt).slice(0,10) }}</small></span><div class="row-actions"><button class="text-btn" @click="detail=item">详情</button><button v-if="item.status!=='MASTERED'" class="text-btn" @click="correct(item)">订正</button><button v-if="!isParent&&item.status==='PENDING_REVIEW'" class="text-btn" @click="review(item)">审核</button></div></div></article></div></LoadState></section><Teleport to="body"><div v-if="detail" class="modal-overlay" @mousedown.self="detail=null"><section class="modal detail-modal" role="dialog" aria-modal="true" aria-labelledby="mistake-title"><header class="modal-header"><div><span class="eyebrow">{{ detail.studentName }} · {{ detail.subject }} · {{ detail.knowledgePoint }}</span><h2 id="mistake-title">{{ detail.title }}</h2></div><button class="icon-btn" aria-label="关闭错题详情" @click="detail=null"><AppIcon name="X" /></button></header><div class="detail-body"><StatusBadge :value="detail.status" /><p v-if="detail.questionText" class="prose">{{detail.questionText}}</p><p class="prose">错误原因：{{ detail.errorReason }}</p><AttachmentList :files="detail.attachments" /><div v-for="correction in detail.corrections" :key="correction.id" class="quote-card"><span class="eyebrow">订正记录 · {{ datetime(correction.createdAt) }}</span><p>{{ correction.text }}</p><AttachmentList :files="correction.attachments" /></div><div v-if="detail.teacherComment" class="quote-card"><span class="eyebrow">老师评语</span><p>{{ detail.teacherComment }}</p></div><h3 v-if="detail.reviews?.length" class="detail-subtitle">间隔复习计划</h3><div v-for="reviewItem in detail.reviews" :key="reviewItem.id" class="review-row"><AppIcon name="CalendarCheck2" :size="17" /><span>{{ reviewItem.dueDate }}</span><StatusBadge :value="reviewItem.status" /><button v-if="!isParent&&reviewItem.status==='PENDING'&&reviewItem.dueDate<=businessDate()" class="text-btn" @click="complete(reviewItem.id)">完成复习</button><span v-else-if="!isParent&&reviewItem.status==='PENDING'" class="muted small-text">尚未到复习日</span></div><h3 v-if="detail.history?.length" class="detail-subtitle">状态与操作历史</h3><div v-for="entry in detail.history" :key="entry.id" class="quote-card"><span class="eyebrow">{{datetime(entry.createdAt)}} · {{entry.actorName}}</span><p>{{label(entry.fromStatus)}} → {{label(entry.toStatus)}}</p><p>{{entry.comment}}</p></div><div class="detail-links"><button v-if="detail.status!=='MASTERED'" class="btn secondary" @click="correct(detail)">提交订正</button><button v-if="!isParent&&detail.status==='PENDING_REVIEW'" class="btn primary" @click="review(detail)">审核掌握情况</button></div></div></section></div></Teleport></template>
